function App() {
  const [web3Modal, setWeb3Modal] = useState(null);
  const [provider, setProvider] = useState(null);
  const [walletConnected, setWalletConnected] = useState(false);
  const [walletAddress, setWalletAddress] = useState('');

  const [productInfo, setProductInfo] = useState(null);
  const [selectedProductId, setSelectedProductId] = useState(null); // ou un ID de produit par défaut

  const [productId, setProductId] = useState('');
  const [productPrice, setProductPrice] = useState(null);
  const [bnbToUsdRate, setBnbToUsdRate] = useState(null);
  const [selectedCurrency, setSelectedCurrency] = useState('USD');
  const [convertedPrice, setConvertedPrice] = useState(null);
  const [contractInstance, setContractInstance] = useState(null); // Déclarez `contractInstance` ici
  const products = {
    product1: { price: 0.001693709562684191, exists: true, title: "Indicateur Daily" },
    product2: { price: 295, exists: true, title: "Indicateur 4h/1h" },
    product3: { price: 495, exists: true, title: "Indicateur 15mn" }
  };










  // Initialisation de Web3Modal pour la connexion aux portefeuilles
  useEffect(() => {
  const modal = new Web3Modal({
    cacheProvider: true, // Gardera en cache la dernière connexion
    providerOptions: {
      walletconnect: {
        package: WalletConnectProvider, // Utilisation de WalletConnectProvider
        options: {
          infuraId: "e759bc5af90042a1b66c5a01aae905af" // Remplace avec ton propre infura ID
        }
      },
      metamask: {
        package: null, // MetaMask ne nécessite pas de package

      },
      trustwallet: {
        package: WalletConnectProvider, // Utilisation de WalletConnectProvider pour Trust Wallet
        options: {
          infuraId: "pDtEhrK4AAiPfirK7qsQI25NJlgrtMu1bBcFDqV4J95GTCAR2d/8Lg" // Remplace avec ton propre infura ID
        }
      },

      // Ajoute d'autres options de portefeuille ici si nécessaire (par exemple : Fortmatic, etc.)
    }
  });

  setWeb3Modal(modal);

  // Vérifie si la modale est présente dans le DOM
  const interval = setInterval(() => {
    const web3ModalElement = document.querySelector('.web3-modal-container');
    if (web3ModalElement) {
      web3ModalElement.style.zIndex = '999999'; // Modale au-dessus de tout
      clearInterval(interval);
    }
  }, 100);

  return () => clearInterval(interval);

}, []);




  // Masquer l'iframe si elle est présente
  const hideIframe = () => {
    const iframe = document.querySelector('iframe');
    if (iframe) {
      iframe.style.display = 'none'; // ou iframe.remove() si tu préfères
    }
  };

  // Appel de la fonction pour masquer l'iframe au moment où Web3Modal est chargé
  hideIframe();


  // Fonction pour reconnecter MetaMask
  const reconnectToMetaMask = async () => {
    if (typeof window.ethereum === "undefined") {
      alert("MetaMask n'est pas installé !");
      return;
    }

    try {

      await window.ethereum.request({
        method: 'wallet_requestPermissions',
        params: [{
          eth_accounts: {}
        }]
      });

      setTimeout(async () => {
        const accounts = await window.ethereum.request({
          method: 'eth_requestAccounts',
        });

        const provider = new ethers.providers.Web3Provider(window.ethereum);
        const signer = provider.getSigner();
        const address = await signer.getAddress();

        setWalletAddress(address);
        setWalletConnected(true);
        alert(`Compte connecté : ${address}`);
      }, 1000);
    } catch (error) {
      console.error('Erreur de connexion à MetaMask :', error);
      alert('Échec de la connexion à MetaMask.');
    }
  };


  // Connexion au wallet via Web3Modal
  const connectWallet = async () => {
    if (!web3Modal) {
      console.error("Web3Modal non initialisé");
      return;
    }

    try {
      console.log("Tentative de connexion au wallet...");


      // Connexion via Web3Modal
      const instance = await web3Modal.connect();
      const newProvider = new ethers.providers.Web3Provider(instance);

      // S'assurer que le provider est correctement défini
      if (!newProvider) {
        console.error("Le fournisseur Web3 n'a pas été correctement créé");
        return;
      }

      setProvider(newProvider);

      // Récupérer l'adresse du wallet
      const signer = newProvider.getSigner();
      const address = await signer.getAddress();

      setWalletAddress(address);
      setWalletConnected(true);

      console.log(`Wallet connecté: ${address}`);
    } catch (error) {
      console.error("Erreur lors de la connexion au portefeuille:", error);
      alert("Erreur de connexion au portefeuille. Veuillez connecter votre wallet.");
      // Ferme Web3Modal
      web3Modal.clearCachedProvider();

      // Relance le processus de reconnexion via MetaMask
      try {
        if (typeof window.ethereum !== "undefined") {
          await reconnectToMetaMask();
        } else {
          alert("MetaMask n'est pas installé.");
        }
      } catch (retryError) {
        console.error("Échec de la reconnexion à MetaMask", retryError);
        alert("La reconnexion à MetaMask a échoué.");
      }
    }
  };


  // Récupération du taux de conversion BNB vers USD
  const getBNBToUSDTRate = async () => {
    try {
      const response = await axios.get('https://api.coingecko.com/api/v3/simple/price?ids=binancecoin&vs_currencies=usd');
      const rate = response.data.binancecoin.usd;

      // Vérifie si le taux est bien récupéré et l'affiche
      console.log("Taux de conversion BNB -> USDT : ", rate);
      setBnbToUsdRate(rate);
    } catch (error) {
      console.error('Erreur lors de la récupération du taux BNB -> USDT', error);
    }
  };

   // Charger les données du contrat et les informations du produit
   useEffect(() => {
    const loadBlockchainData = async () => {
      if (provider) {
        const contractAddress = '0xCd25eee89Bb01603f0E0cf8D8C243966a926761d';
        const contract = new ethers.Contract(contractAddress, contractABI, provider.getSigner());

        try {
          // Suppression de la récupération via le contrat
          // const productDetails = await contract.products(selectedProductId);
          // setProductInfo(productDetails);
          // setProductPrice(productDetails.price);

          setContractInstance(contract); // Cette ligne peut être conservée si tu veux garder une référence au contrat, mais elle est inutilisée pour le moment.
        } catch (error) {
          console.error("Erreur lors de la récupération des informations du produit:", error);
        }
      }
    };
    loadBlockchainData();
    getBNBToUSDTRate();
  }, [provider, selectedProductId]);  // Retirer cette partie puisque tu n'as plus besoin de récupérer les produits du smart contract.









  const [loading, setLoading] = useState(false); // Ajout de l'état loading
  const [transactionInProgress, setTransactionInProgress] = useState(false);



  // Fonction pour approuver USDT
  const approveUSDT = async (amountToSend) => {
    const signer = new ethers.providers.Web3Provider(window.ethereum).getSigner();
    const usdtContract = new ethers.Contract(usdtAddress, usdtABI, signer);

    try {
      const allowance = await usdtContract.allowance(await signer.getAddress(), contractAddress);
      console.log("Allowance actuelle:", allowance.toString());

      if (allowance.lt(amountToSend)) {
        console.log("Allowance insuffisante, approbation en cours...");
        const tx = await usdtContract.approve(contractAddress, amountToSend);
        const receipt = await tx.wait();

        if (receipt.status === 1) {
          console.log("Allowance mise à jour !");
        } else {
          console.error("L'approbation de l'allowance a échoué.");
          throw new Error("Échec de l'approbation de l'allowance.");
        }
      } else {
        console.log("Allowance suffisante.");
      }
    } catch (error) {
      console.error("Erreur lors de l'approbation de l'allowance USDT :", error);
    }
  };




  const [errorMessage, setErrorMessage] = useState('');





// Fonction pour effectuer le paiement
const handlePayment = async () => {
  if (!walletConnected) {
    alert("Veuillez connecter votre wallet avant de procéder.");
    return;
  }

  if (selectedProductId) {
    try {
      const product = products[selectedProductId] || {};

      if (!product || !product.exists) {
        alert("Produit non disponible.");
        return;
      }

      const productPriceInBnb = convertedPrice; // Assumes the product's price is already in BNB

      if (isNaN(productPriceInBnb) || productPriceInBnb <= 0) {
        alert("Prix du produit en BNB invalide.");
        return;
      }

      console.log(`Prix du produit en BNB : ${productPriceInBnb} BNB`);

      // Convertir en Wei
      const amountInWei = ethers.utils.parseUnits(productPriceInBnb.toString(), 18);

      // Vérification de MetaMask
      if (typeof window.ethereum === 'undefined') {
        alert('MetaMask n\'est pas installé. Veuillez installer MetaMask.');
        return;
      }

      // Demander explicitement la connexion avec MetaMask si non connecté
      await window.ethereum.request({ method: 'eth_requestAccounts' });

      // Créer un provider avec le signer
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();

      // Vérifier l'adresse du signer
      const address = await signer.getAddress();
      console.log("Adresse du wallet connecté : ", address);

      // Créer l'instance du contrat
      const contract = new ethers.Contract(contractAddress, contractABI, signer);

      // Estimer les frais de gas pour la transaction
      const estimatedGas = await contract.estimateGas.pay(
        ethers.constants.AddressZero, // Destinataire
        amountInWei, // Montant en Wei
        selectedProductId, {
          value: amountInWei,  // Si c'est un paiement en BNB
        }
      );

      // Vérifier le gas price actuel
      const gasPrice = await provider.getGasPrice();

      // Calculer le coût total en gas (Gas Limit * Gas Price)
      const totalGasCost = estimatedGas.mul(gasPrice);
      console.log('Frais de gas estimés en BNB :', ethers.utils.formatUnits(totalGasCost, 'ether'));

      // Vérifier si l'utilisateur a assez de BNB pour couvrir les frais de gas
      const userBalance = await provider.getBalance(address);
      console.log('Solde de l\'utilisateur en BNB :', ethers.utils.formatUnits(userBalance, 'ether'));

      if (userBalance.lt(totalGasCost)) {
        alert("Vous n'avez pas assez de BNB pour couvrir les frais de gas.");
        return;
      }

      // Créer la transaction via `populateTransaction`
      const tx = await contract.populateTransaction.pay(
        ethers.constants.AddressZero, // Destinataire
        amountInWei, // Montant en Wei
        selectedProductId, {
          value: amountInWei,  // Si c'est un paiement en BNB
          gasLimit: estimatedGas,  // Utiliser le gas estimé
        }
      );

      console.log('Transaction à envoyer:', tx);

      // **Envoyer explicitement la transaction via signer.sendTransaction()**
      const txResponse = await signer.sendTransaction(tx);

      console.log('Transaction envoyée:', txResponse);

      // Attendre la confirmation de la transaction
      await txResponse.wait();
      console.log("Transaction confirmée");

      alert("Paiement effectué avec succès!");
    } catch (error) {
      console.error("Erreur lors du paiement:", error);
      alert("Une erreur est survenue lors du paiement.");
    }
  } else {
    alert("Produit ou prix non valide.");
  }
};




const handleCheckProductInfo = async (productId) => {
    if (!walletConnected) {
      alert("Veuillez connecter votre wallet avant de procéder.");
      return;
    }

    try {
      // Récupérer le provider et le signer
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();

      const contract = new ethers.Contract(contractAddress, contractABI, signer);

      // Appeler la fonction de consultation de la mapping 'products'
      const [priceInWei, exists] = await contract.products(productId);

      if (!exists) {
        alert("Produit non disponible.");
        return;
      }

      // Ici, on récupère directement l'entier 'priceInWei' sans conversion
      console.log(`Produit ${productId} - Prix: ${priceInWei} (En entier)`);

      // Afficher les informations du produit dans la console ou dans un alert
      alert(`Produit ${productId} trouvé !\nPrix: ${priceInWei} (En entier)`);

    } catch (error) {
      console.error("Erreur lors de la récupération des informations du produit:", error);
      alert("Une erreur est survenue lors de la récupération des informations du produit.");
    }
};











  // Vérification de l'allowance
  const checkAllowance = async (amount) => {
    const tokenContract = new ethers.Contract(usdtAddress, usdtABI, provider.getSigner());
    const allowance = await tokenContract.allowance(walletAddress, contractInstance.address);

    if (allowance.lt(amount)) {
      console.log("Allowance insuffisante, demande d'approbation...");
      await approveUSDT(amount);  // Approuve le montant si l'allowance est insuffisante
    } else {
      console.log("Allowance suffisante");
      // Proceed with the payment if allowance is sufficient
    }
  };


  // Mise à jour des informations du produit

  const updateProductInfo = (selectedProductId) => {
    const productDetails = products[selectedProductId];  // Utilisation de l'objet local products
    if (productDetails) {
      const { price, exists } = productDetails;
      setProductPrice(price);  // Met à jour le prix
      setProductInfo({ price, exists });  // Met à jour les informations du produit

      // Si le taux de conversion est disponible, calculer le prix en BNB
      if (bnbToUsdRate) {
        const convertedPrice = Math.ceil(price * bnbToUsdRate);

        setConvertedPrice(convertedPrice.toString());
      }
    } else {
      setProductInfo({ exists: false });  // Si le produit n'existe pas
      setProductPrice(null);
      setConvertedPrice(null);
    }
  };





  async function getProductPriceInBNB(productId) {
    // Récupérer le prix en USDT du smart contract
    const product = await contractInstance.products(productId);
    if (!product.exists) {
        alert("Produit inexistant");
        return;
    }

    const priceInUSDT = product.price;

    // Conversion du prix en USDT en BNB (à l'aide d'un oracle ou d'un service externe)
    const bnbToUSDTRate = await getBNBToUSDTRate(); // Récupérer le taux de conversion

    const priceInBNB = priceInUSDT / bnbToUSDTRate;

    console.log("Prix en USDT:", priceInUSDT);
    console.log("Prix en BNB:", priceInBNB);

    return { priceInUSDT, priceInBNB };
}


const fetchProductPrice = async (productId) => {
  if (!window.ethereum) {
    alert('MetaMask est requis pour interagir avec ce contrat.');
    return;
  }

  const provider = new ethers.providers.Web3Provider(window.ethereum);
  const contract = new ethers.Contract(contractAddress, contractABI, provider);

  try {
    setLoading(true);
    // Récupérer le produit depuis le smart contract
    const product = await contract.products(productId);

    if (product.exists) {
      let priceInWei = product.price.toString();  // Récupère la valeur brute du prix (en Wei)

      // Affiche la valeur brute du prix pour débogage
      console.log('Valeur brute récupérée du smart contract :', priceInWei);

      // Utiliser `ethers.utils.formatUnits()` pour convertir en BNB (18 décimales par défaut)
      let priceBNB = ethers.utils.formatUnits(priceInWei, 18);

      console.log('Prix du produit après conversion :', priceBNB, 'BNB');

      // Retourner le prix en BNB
      return { priceInBNB: parseFloat(priceBNB) }; // Assure-toi de retourner un nombre flottant
    } else {
      console.log('Produit non trouvé');
      return null;  // Retourner null si le produit n'existe pas
    }
  } catch (error) {
    console.error('Erreur lors de la récupération du prix', error);
  } finally {
    setLoading(false);
  }
};







// Fonction pour vérifier si un produit existe dans le contrat
const checkProductExistence = async (productId) => {
  try {
    console.log(`Vérification de l'existence du produit : ${productId}`);
    const provider = new ethers.providers.Web3Provider(window.ethereum);
    const contract = new ethers.Contract(contractAddress, contractABI, provider);

    // Appeler la fonction "products" du contrat pour vérifier si le produit existe
    const product = await contract.products(productId);

    if (product.exists) {
      console.log(`Produit trouvé : ${productId}`);
      return true; // Le produit existe
    } else {
      console.log(`Produit non trouvé : ${productId}`);
      return false; // Le produit n'existe pas
    }
  } catch (err) {
    console.error("Erreur lors de la vérification du produit :", err);
    alert("Erreur lors de la vérification du produit.");
    return false; // En cas d'erreur, on retourne false
  }
};


// Fonction qui sera appelée au clic sur le bouton "Acheter"
const handleBuyButtonClick = async () => {
  console.log("Clic sur le bouton Payer !");

  // Vérifier si le produit existe avant de procéder
  const productExists = await checkProductExistence(selectedProductId);

  if (productExists) {
    // Si le produit existe, procéder à la récupération du prix
    const result = await fetchProductPrice(selectedProductId);
    console.log("Résultat fetchProductPrice:", result);

    if (result?.priceInBNB) {
      const gasPrice = ethers.utils.parseUnits("5", "gwei");
      const gasLimit = 300000;
      const amountIn = ethers.utils.parseEther(result.priceInBNB.toString());

      // Assure-toi d'utiliser le bon contrat pour appeler la fonction `pay`
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();
      const contract = new ethers.Contract(contractAddress, contractABI, signer);

      try {
        console.log("Tentative de paiement avec le montant:", amountIn.toString());

        // Appel à la fonction `pay` du contrat avec le montant, l'adresse du token (0x0 pour BNB), et l'ID du produit
        const tx = await contract.pay(
          "0x0000000000000000000000000000000000000000", // Adresse 0 pour BNB
          amountIn,
          selectedProductId, // ID du produit
          {
            value: amountIn, // Pour les paiements en BNB, la valeur est attachée à la transaction
            gasLimit: gasLimit,
            gasPrice: gasPrice,
          }
        );

        console.log("Transaction envoyée:", tx);
        // Attendre la confirmation de la transaction
        await tx.wait();
        alert("Achat effectué avec succès !");
      } catch (error) {
        console.error("Erreur lors du paiement:", error);
        alert("Erreur lors du paiement. Veuillez réessayer.");
      }
